+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 1.75rem 1.5rem;
+  margin-bottom: 1.5rem;
+  text-align: center;
+  box-shadow: var(--shadow);
+}
+
+.score-display {
+  font-size: 3.5rem;
+  font-weight: 700;
+  line-height: 1;
+  margin-bottom: 0.5rem;
+  letter-spacing: -0.02em;
+}
+
+.score-perfect { color: var(--success); }
+.score-good    { color: var(--accent); }
+.score-poor    { color: var(--error-color); }
+
+.score-label {
+  color: var(--text-muted);
+  font-size: 0.9375rem;
+}
+
+.result-questions {
+  display: flex;
+  flex-direction: column;
+  gap: 1rem;
+}
+
+.result-question {
+  background: var(--surface);
+  border: 1px solid var(--border);
+  border-radius: var(--radius-lg);
+  padding: 1.25rem 1.5rem;
+  box-shadow: var(--shadow);
+}
+
+.result-question.correct  { border-color: var(--success); }
+.result-question.incorrect { border-color: var(--error-color); }
+
+.result-question-header {
+  display: flex;
+  align-items: flex-start;
+  gap: 0.75rem;
+  margin-bottom: 0.875rem;
+}
+
+.result-status-icon {
+  font-size: 1.1rem;
+  flex-shrink: 0;
+  line-height: 1.55;
+}
+
+.result-question-text {
+  font-weight: 600;
+  color: var(--text);
+  font-size: 0.9375rem;
+  line-height: 1.5;
+}
+
+.result-options {
+  list-style: none;
+  display: flex;
+  flex-direction: column;
+  gap: 0.375rem;
+}
+
+.result-option {
+  display: flex;
+  align-items: center;
+  gap: 0.5rem;
+  font-size: 0.875rem;
+  padding: 0.375rem 0.625rem;
+  border-radius: 4px;
+  color: var(--text-muted);
+}
+
+.result-option.was-selected.is-correct {
+  color: var(--success);
+  background: var(--success-bg);
+}
+
+.result-option.was-selected.is-wrong {
+  color: var(--error-color);
+  background: var(--error-bg);
+}
+
+.result-option.not-selected.is-correct {
+  color: var(--missed-color);
+  background: var(--missed-bg);
+  font-style: italic;
+}
+
+.option-icon {
+  font-size: 0.8125rem;
+  flex-shrink: 0;
+  width: 1em;
+  text-align: center;
+  font-style: normal;
+}
+
+/* ===== Reduced motion ===== */
+@media (prefers-reduced-motion: reduce) {
+  *,
+  *::before,
+  *::after {
+    transition-duration: 0.01ms !important;
+    animation-duration: 0.01ms !important;
+  }
+}
+
+/* ===== Forced colors (Windows High Contrast) ===== */
+@media (forced-colors: active) {
+  .help-text {
+    border-left-color: ButtonText;
+    background: transparent;
+  }
+  .checkbox-option:has(input:checked) {
+    border-color: Highlight;
+    background: transparent;
+  }
+  .result-option.was-selected.is-correct,
+  .result-option.was-selected.is-wrong,
+  .result-option.not-selected.is-correct {
+    background: transparent;
+  }
+  .btn-submit {
+    forced-color-adjust: none;
+  }
+}
+
+/* ===== Reflow — 320 CSS px ===== */
+@media (max-width: 420px) {
+  body {
+    padding: 1rem 0.75rem 3rem;
+  }
+  fieldset {
+    padding: 1rem;
+  }
+  .form-actions {
+    justify-content: stretch;
+  }
+  .btn-submit {
+    width: 100%;
+  }
+  .result-summary {
+    padding: 1.25rem 1rem;
+  }
+  .result-question {
+    padding: 1rem;
+  }
+}
+
')

