+ *           options: Array<{value:string, label:string}> }} props
+ * @returns {HTMLDivElement}
+ */
+function QuestionCard({ id, number, text, helpText, options }) {
+  const formField = document.createElement("div");
+  formField.className = "form-field";
+
+  const fieldset = document.createElement("fieldset");
+  if (helpText) {
+    fieldset.setAttribute("aria-describedby", `${id}-help`);
+  }
+
+  const legend = document.createElement("legend");
+  legend.textContent = `${number}. ${text}`;
+  fieldset.appendChild(legend);
+
+  if (helpText) {
+    const helpEl = document.createElement("p");
+    helpEl.id = `${id}-help`;
+    helpEl.className = "help-text";
+    helpEl.textContent = helpText;
+    fieldset.appendChild(helpEl);
+  }
+
+  const optionsWrapper = document.createElement("div");
+  optionsWrapper.className = "checkbox-options";
+  options.forEach((opt) =>
+    optionsWrapper.appendChild(CheckboxOption({ questionId: id, ...opt }))
+  );
+
+  fieldset.appendChild(optionsWrapper);
+  formField.appendChild(fieldset);
+  return formField;
+}
+
+/**
+ * ResultOptionItem — renders one list item showing whether an option was
+ * correctly selected, incorrectly selected, missed, or correctly skipped.
+ * @param {{ option: {value:string,label:string}, wasSelected: boolean,
+ *           isCorrectAnswer: boolean }} props
+ * @returns {HTMLLIElement}
+ */
+function ResultOptionItem({ option, wasSelected, isCorrectAnswer }) {
+  const li = document.createElement("li");
+  li.className = [
+    "result-option",
+    wasSelected ? "was-selected" : "not-selected",
+    isCorrectAnswer ? "is-correct" : "is-wrong",
+  ].join(" ");
+
+  const icon = document.createElement("span");
+  icon.className = "option-icon";
+  icon.setAttribute("aria-hidden", "true");
+
+  if      (wasSelected && isCorrectAnswer)  icon.textContent = "✓";
+  else if (wasSelected && !isCorrectAnswer) icon.textContent = "✗";
+  else if (!wasSelected && isCorrectAnswer) icon.textContent = "○";
+  else                                      icon.textContent = "–";
+
+  // Visible label prefix for screen-reader context
+  const srPrefix = document.createElement("span");
+  srPrefix.className = "sr-only";
+  if      (wasSelected && isCorrectAnswer)  srPrefix.textContent = "Correctly selected: ";
+  else if (wasSelected && !isCorrectAnswer) srPrefix.textContent = "Incorrectly selected: ";
+  else if (!wasSelected && isCorrectAnswer) srPrefix.textContent = "Missed correct answer: ";
+
+  li.appendChild(icon);
+  li.appendChild(srPrefix);
+  li.appendChild(document.createTextNode(option.label));
+  return li;
+}
+
+/**
+ * ResultQuestionCard — renders one question's result block showing the
+ * pass/fail status and per-option feedback.
+ * @param {{ question: object, number: number, userAnswers: Set<string> }} props
+ * @returns {HTMLDivElement}
+ */
+function ResultQuestionCard({ question, number, userAnswers }) {
+  const { text, options, correct } = question;
+  const isCorrect =
+    userAnswers.size === correct.size &&
+    [...correct].every((v) => userAnswers.has(v));
+
+  const card = document.createElement("div");
+  card.className = `result-question ${isCorrect ? "correct" : "incorrect"}`;
+
+  // Header with status icon + question text
+  const header = document.createElement("div");
+  header.className = "result-question-header";
+
+  const icon = document.createElement("span");
+  icon.className = "result-status-icon";
+  icon.setAttribute("aria-hidden", "true");
+  icon.textContent = isCorrect ? "✅" : "❌";
+
+  const questionText = document.createElement("span");
+  questionText.className = "result-question-text";
+  questionText.textContent = `${number}. ${text}`;
+
+  header.appendChild(icon);
+  header.appendChild(questionText);
+  card.appendChild(header);
+
+  // Options list
+  const list = document.createElement("ul");
+  list.className = "result-options";
+  list.setAttribute(
+    "aria-label",
+    `Answer breakdown for question ${number}`
+  );
+
+  options.forEach((opt) =>
+    list.appendChild(
+      ResultOptionItem({
+        option: opt,
+        wasSelected: userAnswers.has(opt.value),
+        isCorrectAnswer: correct.has(opt.value),
+      })
+    )
+  );
+
+  card.appendChild(list);
+  return card;
+}
+
+/**
+ * QuizResult — renders the full results panel: score summary + per-question
+ * result cards.
+ * @param {{ questions: object[], allUserAnswers: Map<string, Set<string>> }} props
+ * @returns {DocumentFragment}
+ */
+function QuizResult({ questions, allUserAnswers }) {
+  const correctCount = questions.filter((q) => {
+    const ua = allUserAnswers.get(q.id);
+    return ua.size === q.correct.size && [...q.correct].every((v) => ua.has(v));
+  }).length;
+
+  const total = questions.length;
+  const frag = document.createDocumentFragment();
+
+  // Heading — receives programmatic focus so keyboard users land here
+  const heading = document.createElement("h2");
+  heading.className = "result-heading";
+  heading.textContent = "Your Results";
+  heading.tabIndex = -1;
+  frag.appendChild(heading);
+
+  // Score summary card
+  const summary = document.createElement("div");
+  summary.className = "result-summary";
+  summary.setAttribute("aria-label", `Score: ${correctCount} out of ${total}`);
+
+  const scoreEl = document.createElement("div");
+  scoreEl.className = [
+    "score-display",
+    correctCount === total
+      ? "score-perfect"
+      : correctCount >= Math.ceil(total / 2)
+      ? "score-good"
+      : "score-poor",
+  ].join(" ");
+  scoreEl.setAttribute("aria-hidden", "true"); // announced via aria-label on parent
+  scoreEl.textContent = `${correctCount} / ${total}`;
+
+  const scoreLabel = document.createElement("p");
+  scoreLabel.className = "score-label";
+  scoreLabel.textContent =
+    correctCount === total
+      ? "Perfect score — excellent work! 🎉"
+      : correctCount === 0
+      ? "No correct answers. Review the results below."
+      : `You got ${correctCount} out of ${total} correct.`;
+
+  summary.appendChild(scoreEl);
+  summary.appendChild(scoreLabel);
+  frag.appendChild(summary);
+
+  // Per-question results
+  const questionsContainer = document.createElement("div");
+  questionsContainer.className = "result-questions";
+
+  questions.forEach((q, i) =>
+    questionsContainer.appendChild(
+      ResultQuestionCard({
+        question: q,
+        number: i + 1,
+        userAnswers: allUserAnswers.get(q.id),
+      })
+    )
+  );
+
+  frag.appendChild(questionsContainer);
+  return frag;
+}
+
+/**
+ * QuizApp — mounts all QuestionCard components into the given container.
+ * @param {{ questions: object[], container: HTMLElement }} props
+ */
+function QuizApp({ questions, container }) {
+  questions.forEach((q, i) =>
+    container.appendChild(QuestionCard({ ...q, number: i + 1 }))
+  );
+}
+
+// ─── Event handling ───────────────────────────────────────────────────────────
+
+function getSelectedValues(questionId) {
+  return new Set(
+    [...document.querySelectorAll(
+      `input[type="checkbox"][name="${questionId}"]:checked`
+    )].map((cb) => cb.value)
+  );
+}
+
+function handleSubmit(event) {
+  event.preventDefault();
+
+  const allUserAnswers = new Map(
+    QUESTIONS.map((q) => [q.id, getSelectedValues(q.id)])
+  );
+
+  const resultContainer = document.getElementById("quiz-result");
+  resultContainer.innerHTML = "";
+  resultContainer.appendChild(QuizResult({ questions: QUESTIONS, allUserAnswers }));
+
+  // Scroll to results, respecting reduced-motion preference
+  const prefersReducedMotion = window.matchMedia(
+    "(prefers-reduced-motion: reduce)"
+  ).matches;
+
+  resultContainer.scrollIntoView({
+    behavior: prefersReducedMotion ? "auto" : "smooth",
+    block: "start",
+  });
+
+  // Move focus to the result heading so keyboard/AT users land in context
+  const heading = resultContainer.querySelector("h2");
+  if (heading) heading.focus();
+}
+
+// ─── Init ────────────────────────────────────────────────────────────────────
+
+document.addEventListener("DOMContentLoaded", () => {
+  QuizApp({
+    questions: QUESTIONS,
+    container: document.getElementById("quiz-questions"),
+  });
+
+  document.getElementById("quiz-form").addEventListener("submit", handleSubmit);
+});
+
')

