  --accent: #58a6ff;
  --accent-bg: rgba(88, 166, 255, 0.1);
  --success: #3fb950;
  --success-bg: rgba(63, 185, 80, 0.12);
  --error-color: #f85149;
  --error-bg: rgba(248, 81, 73, 0.1);
  --missed-color: #d29922;
  --missed-bg: rgba(210, 153, 34, 0.1);
  --btn-bg: #238636;
  --btn-hover: #1e7a2d;
  --btn-active: #165c22;
  --radius: 8px;
  --radius-lg: 12px;
  --shadow: 0 1px 4px rgba(0, 0, 0, 0.5);
  --transition: 150ms ease;
}

/* ===== Reset ===== */
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ===== Base ===== */
body {
  background-color: var(--bg);
  color: var(--text);
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", system-ui,
    sans-serif;
  font-size: 1rem;
  line-height: 1.6;
  min-height: 100vh;
  padding: 2.5rem 1rem 4rem;
}

/* ===== Skip link ===== */
.skip-link {
  position: absolute;
  top: -100%;
  left: 1rem;
  background: var(--accent);
  color: #0d1117;
  padding: 0.5rem 1rem;
  border-radius: var(--radius);
  font-weight: 600;
  text-decoration: none;
  z-index: 100;
  transition: top var(--transition);
}
.skip-link:focus {
  top: 1rem;
}

/* ===== Screen-reader only ===== */
.sr-only {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

/* ===== Layout ===== */
.container {
  max-width: 720px;
  margin: 0 auto;
}

/* ===== Quiz header ===== */
.quiz-header {
  margin-bottom: 2rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border);
}

h1 {
  font-size: clamp(1.5rem, 4vw, 2rem);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: 0.5rem;
}

.quiz-intro {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

/* ===== Form field ===== */
.form-field {
  margin-bottom: 1.25rem;
}

/* ===== Fieldset & legend ===== */
fieldset {
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  background: var(--surface);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow);
}

legend {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text);
  line-height: 1.5;
  padding: 0 0.25rem;
  float: left;
  width: 100%;
  margin-bottom: 0.75rem;
}

/* Clear the legend float so following content sits below it */
legend + * {
  clear: both;
}

/* ===== Help text ===== */
.help-text {
  font-size: 0.875rem;
  color: var(--text-muted);
  margin-bottom: 1rem;
  padding: 0.625rem 0.875rem;
  background: rgba(88, 166, 255, 0.06);
  border-left: 3px solid var(--accent);
  border-radius: 0 var(--radius) var(--radius) 0;
}

/* ===== Checkbox options ===== */
.checkbox-options {
  display: flex;
  flex-direction: column;
  gap: 0.5rem;
}

.checkbox-option {
  display: grid;
  grid-template-columns: auto 1fr;
  align-items: center;
  gap: 0.75rem;
  padding: 0.75rem 1rem;
  border: 1px solid var(--border);
  border-radius: var(--radius);
  transition: background-color var(--transition), border-color var(--transition);
}

.checkbox-option:has(input:checked) {
  background: var(--accent-bg);
  border-color: var(--accent);
}

.checkbox-option:hover {
  background: rgba(255, 255, 255, 0.04);
}

.checkbox-option:has(input:checked):hover {
  background: rgba(88, 166, 255, 0.15);
}

.checkbox-option input[type="checkbox"] {
  width: 1.125rem;
  height: 1.125rem;
  accent-color: var(--accent);
  cursor: pointer;
  flex-shrink: 0;
}

.checkbox-option label {
  cursor: pointer;
  color: var(--text);
  font-size: 0.9375rem;
  line-height: 1.4;
  user-select: none;
}

/* ===== Form actions ===== */
.form-actions {
  margin-top: 2rem;
  display: flex;
  justify-content: flex-end;
}

/* ===== Submit button ===== */
.btn-submit {
  background: var(--btn-bg);
  color: #ffffff;
  border: none;
  padding: 0.75rem 2rem;
  border-radius: var(--radius);
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  min-width: 160px;
  transition: background-color var(--transition), transform var(--transition);
}

.btn-submit:hover {
  background: var(--btn-hover);
}

.btn-submit:active {
  background: var(--btn-active);
  transform: translateY(1px);
}

/* ===== Focus styles ===== */
:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 2px;
  border-radius: 2px;
}

/* ===== Quiz result ===== */
.quiz-result {
  margin-top: 2.5rem;
}

.quiz-result:empty {
  display: none;
}

.result-heading {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text);
}

.result-summary {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.75rem 1.5rem;
  margin-bottom: 1.5rem;
  text-align: center;
  box-shadow: var(--shadow);
}

.score-display {
  font-size: 3.5rem;
  font-weight: 700;
  line-height: 1;
  margin-bottom: 0.5rem;
  letter-spacing: -0.02em;
}

.score-perfect { color: var(--success); }
.score-good    { color: var(--accent); }
.score-poor    { color: var(--error-color); }

.score-label {
  color: var(--text-muted);
  font-size: 0.9375rem;
}

.result-questions {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.result-question {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  padding: 1.25rem 1.5rem;
  box-shadow: var(--shadow);
}

.result-question.correct  { border-color: var(--success); }
.result-question.incorrect { border-color: var(--error-color); }

.result-question-header {
  display: flex;
  align-items: flex-start;
  gap: 0.75rem;
  margin-bottom: 0.875rem;
}

.result-status-icon {
  font-size: 1.1rem;
  flex-shrink: 0;
  line-height: 1.55;
}

.result-question-text {
  font-weight: 600;
  color: var(--text);
  font-size: 0.9375rem;
  line-height: 1.5;
}

.result-options {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 0.375rem;
}

.result-option {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  font-size: 0.875rem;
  padding: 0.375rem 0.625rem;
  border-radius: 4px;
  color: var(--text-muted);
}

.result-option.was-selected.is-correct {
  color: var(--success);
  background: var(--success-bg);
}

.result-option.was-selected.is-wrong {
  color: var(--error-color);
  background: var(--error-bg);
}

.result-option.not-selected.is-correct {
  color: var(--missed-color);
  background: var(--missed-bg);
  font-style: italic;
}

.option-icon {
  font-size: 0.8125rem;
  flex-shrink: 0;
  width: 1em;
  text-align: center;
  font-style: normal;
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    transition-duration: 0.01ms !important;
    animation-duration: 0.01ms !important;
  }
}

/* ===== Forced colors (Windows High Contrast) ===== */
@media (forced-colors: active) {
  .help-text {
    border-left-color: ButtonText;
    background: transparent;
  }
  .checkbox-option:has(input:checked) {
    border-color: Highlight;
    background: transparent;
  }
  .result-option.was-selected.is-correct,
  .result-option.was-selected.is-wrong,
  .result-option.not-selected.is-correct {
    background: transparent;
  }
  .btn-submit {
    forced-color-adjust: none;
  }
}

/* ===== Reflow — 320 CSS px ===== */
@media (max-width: 420px) {
  body {
    padding: 1rem 0.75rem 3rem;
  }
  fieldset {
    padding: 1rem;
  }
  .form-actions {
    justify-content: stretch;
  }
  .btn-submit {
    width: 100%;
  }
  .result-summary {
    padding: 1.25rem 1rem;
  }
  .result-question {
    padding: 1rem;
  }
}
