const { chromium } = require("playwright");
const path = require("path");

async function audit(label, setupFn) {
  const b = await chromium.launch();
  const page = await b.newPage();
  const dir = path.resolve(".");
  await page.goto("file://" + dir + "/index.html", { waitUntil: "networkidle" });
  if (setupFn) await setupFn(page);
  await page.addScriptTag({ path: "/tmp/axe.min.js" });
  const r = await page.evaluate(async () => axe.run(document, {}));
  await b.close();

  const wcag = r.violations.filter(v => !v.tags.includes("best-practice"));
  const bp   = r.violations.filter(v =>  v.tags.includes("best-practice"));

  console.log(`\n=== ${label} ===`);
  if (wcag.length === 0 && bp.length === 0) {
    console.log("PASS — 0 violations");
  } else {
    wcag.forEach(v => console.log(`WCAG FAIL [${v.impact}] ${v.id}: ${v.description}\n  targets: ${v.nodes.map(n=>n.target).join(', ')}\n  ${v.nodes.map(n=>n.failureSummary).join('\n  ')}`));
    bp.forEach(v   => console.log(`BEST-PRACTICE [warn] ${v.id}: ${v.description}`));
  }
  return wcag.length;
}

(async () => {
  let totalFails = 0;

  totalFails += await audit("Initial page load", null);

  totalFails += await audit("Post-submit state", async (page) => {
    await page.check("#q1-java");
    await page.check("#q1-typescript");
    await page.check("#q2-haskell");
    await page.check("#q3-rust");
    await page.click(".btn-submit");
    await page.waitForSelector(".quiz-result h2");
  });

  console.log(`\n=== SUMMARY: ${totalFails === 0 ? "PASS" : "FAIL"} (${totalFails} WCAG violations) ===`);
  process.exit(totalFails ? 1 : 0);
})();
EOF
